# Project state now remembers every discovered session plus missing/recovery provenance.
replace_fn('normalizeProjectState', """function normalizeProjectState(v){let x=v&&typeof v==='object'?v:{},projects=Array.isArray(x.projects)?x.projects:[];projects=projects.map(p=>({id:String(p?.id||uid()),name:String(p?.name||'Project').trim()||'Project',sessions:[...new Set((Array.isArray(p?.sessions)?p.sessions:[]).map(String).filter(Boolean))],activeSession:String(p?.activeSession||'')}));if(!projects.length)projects=[{id:'general',name:'General',sessions:[],activeSession:''}];let active=(x.activeProjectId==='__unassigned__'||projects.some(p=>p.id===x.activeProjectId))?x.activeProjectId:projects[0].id,normMap=o=>{let r={};if(o&&typeof o==='object')for(let[k,val]of Object.entries(o))if(k)r[String(k)]={...(val&&typeof val==='object'?val:{})};return r};return{schema:2,activeProjectId:active,unassignedActive:String(x.unassignedActive||''),projects,known:normMap(x.known),missing:normMap(x.missing),recovered:normMap(x.recovered)}}""")

helpers="""
const UNASSIGNED_ID='__unassigned__';
function assignedProjectFor(k){return projects().find(p=>p.sessions.includes(k))||null}
function liveKeySet(){return new Set(state.sessions.map(x=>x.key))}
function trashKeySet(){return new Set(Object.keys(trashBucket()))}
function unassignedSessionKeys(){let assigned=new Set(projects().flatMap(p=>p.sessions)),trash=trashKeySet(),missing=new Set(Object.keys(state.projectState?.missing||{}));return state.sessions.map(x=>x.key).filter(k=>!assigned.has(k)&&!trash.has(k)&&!missing.has(k))}
function isUnassignedView(){return state.settings.clientType==='botschat'&&state.projectState?.activeProjectId===UNASSIGNED_ID}
function recoveredMeta(k){return state.projectState?.recovered?.[k]||null}
function knownMeta(k){return state.projectState?.known?.[k]||state.projectState?.missing?.[k]||recoveredMeta(k)||null}
function disposition(k){if(trashBucket()[k])return'soft-deleted';if(state.projectState?.missing?.[k])return'missing';let p=assignedProjectFor(k);return p?'assigned':'unassigned'}
function setActiveViewSession(k){if(isUnassignedView())state.projectState.unassignedActive=k;else{let p=activeProject();if(p&&p.id!==UNASSIGNED_ID)p.activeSession=k}saveProjectState()}
"""
one("function projects(){if(!state.projectState)state.projectState=loadProjectState();return state.projectState.projects}","function projects(){if(!state.projectState)state.projectState=loadProjectState();return state.projectState.projects}\n"+helpers,'orphan helper insertion')

replace_fn('activeProject',"""function activeProject(){let ps=projects();if(state.projectState.activeProjectId===UNASSIGNED_ID)return{id:UNASSIGNED_ID,name:'Unassigned',sessions:unassignedSessionKeys(),activeSession:state.projectState.unassignedActive||''};return ps.find(p=>p.id===state.projectState.activeProjectId)||ps[0]}""")

# Reconcile all known sessions. Missing is explicit, and recovery always returns to Unassigned.
replace_fn('reconcileProjects',"""function reconcileProjects(previous=[]){if(!state.projectState)state.projectState=loadProjectState();let ps=state.projectState,now=new Map(state.sessions.map(x=>[x.key,x])),prev=new Map((Array.isArray(previous)?previous:[]).map(x=>[x.key,x])),trash=trashKeySet(),changed=false,projectOf=new Map();for(let p of ps.projects)for(let k of p.sessions)projectOf.set(k,p);for(let row of state.sessions){let old=ps.known[row.key]||{},label=name(row);ps.known[row.key]={label,lastSeen:Date.now(),sessionId:row.sessionId||old.sessionId||null,agentId:row.agentId||old.agentId||null};if(ps.missing[row.key]){let m=ps.missing[row.key],p=projectOf.get(row.key);if(p){p.sessions=p.sessions.filter(x=>x!==row.key);if(p.activeSession===row.key)p.activeSession=p.sessions[0]||''}ps.recovered[row.key]={label:m.label||label,previousProjectId:m.previousProjectId||null,previousProjectName:m.previousProjectName||'',missingSince:m.missingSince||null,recoveredAt:Date.now(),reason:'recovered'};delete ps.missing[row.key];changed=true}}let candidates=new Set([...Object.keys(ps.known),...ps.projects.flatMap(p=>p.sessions)]);for(let k of candidates){if(now.has(k)||trash.has(k)||ps.missing[k])continue;let p=projectOf.get(k),old=ps.known[k]||{},prior=prev.get(k),label=old.label||name(prior)||k;ps.missing[k]={label,previousProjectId:p?.id||null,previousProjectName:p?.name||'',missingSince:Date.now(),lastSeen:old.lastSeen||null,sessionId:old.sessionId||prior?.sessionId||null,agentId:old.agentId||prior?.agentId||null};if(p){p.sessions=p.sessions.filter(x=>x!==k);if(p.activeSession===k)p.activeSession=p.sessions[0]||''}delete ps.recovered[k];changed=true}for(let k of trash){for(let p of ps.projects)if(p.sessions.includes(k)){p.sessions=p.sessions.filter(x=>x!==k);if(p.activeSession===k)p.activeSession=p.sessions[0]||'';changed=true}if(ps.missing[k]){delete ps.missing[k];changed=true}if(ps.recovered[k]){delete ps.recovered[k];changed=true}}if(ps.unassignedActive&&!now.has(ps.unassignedActive))ps.unassignedActive='';if(changed)saveProjectState();else{let all={};try{all=JSON.parse(localStorage.getItem(K.projects)||'{}')||{}}catch{}all[projectScope()]=normalizeProjectState(ps);localStorage.setItem(K.projects,JSON.stringify(all))}}""")

replace_fn('saveTrashBucket',"""function saveTrashBucket(b){let all=trashStore();all[trashScope()]=b;localStorage.setItem(K.trash,JSON.stringify(all));sotEmit('trash.snapshot',{scope:trashScope(),bucket:b})}""")

replace_fn('softDeleteSession',"""function softDeleteSession(k){let row=state.sessions.find(x=>x.key===k),meta=knownMeta(k)||{},p=assignedProjectFor(k),m=state.projectState?.missing?.[k],label=row?name(row):(m?.label||meta.label||k),b=trashBucket();b[k]={key:k,label,sessionId:row?.sessionId||m?.sessionId||meta.sessionId||null,agentId:row?.agentId||m?.agentId||meta.agentId||null,deletedAt:Date.now(),previousProjectId:p?.id||m?.previousProjectId||null,previousProjectName:p?.name||m?.previousProjectName||'',previousDisposition:disposition(k)};if(state.projectState){for(let q of projects()){q.sessions=q.sessions.filter(x=>x!==k);if(q.activeSession===k)q.activeSession=q.sessions[0]||''}delete state.projectState.missing[k];delete state.projectState.recovered[k];if(state.projectState.unassignedActive===k)state.projectState.unassignedActive='';saveProjectState()}saveTrashBucket(b);if(state.current?.key===k)clearSelection();renderSessions();renderProjectTabs();toast('Session moved to Recycle bin','ok');dbg('SESS','Soft deleted locally',{key:k})}""")

replace_fn('restoreSession',"""function restoreSession(k){let b=trashBucket(),t=b[k];if(!t)return;delete b[k];saveTrashBucket(b);if(!state.projectState)state.projectState=loadProjectState();state.projectState.recovered[k]={label:t.label||k,previousProjectId:t.previousProjectId||null,previousProjectName:t.previousProjectName||'',recoveredAt:Date.now(),reason:'restored'};delete state.projectState.missing[k];for(let p of projects())p.sessions=p.sessions.filter(x=>x!==k);state.projectState.activeProjectId=UNASSIGNED_ID;state.projectState.unassignedActive=state.sessions.some(x=>x.key===k)?k:'';saveProjectState();renderSessions();renderProjectTabs();toast('Session restored to Unassigned','ok');dbg('SESS','Restored from recycle bin to Unassigned',{key:k,previousProjectId:t.previousProjectId||null})}""")

replace_fn('permanentDeleteSession',"""async function permanentDeleteSession(k){let b=trashBucket(),t=b[k],row=state.sessions.find(x=>x.key===k),s=row||t;if(!s)return;let ok=confirm(`Delete ${name(s)} from OpenClaw?\n\nThis removes the session entry. Session Manager will not erase the transcript directly; OpenClaw is asked to archive/rename it using its own session deletion lifecycle.`);if(!ok)return;try{let params={key:k,deleteTranscript:true,...(s.agentId?{agentId:s.agentId}:{})},r=await rpc('sessions.delete',params,30000);if(Array.isArray(r?.archived))for(let path of r.archived)state.archivePaths.push({path:String(path),key:k,observedAt:Date.now(),source:'sessions.delete'});delete b[k];saveTrashBucket(b);if(state.projectState){for(let p of projects())p.sessions=p.sessions.filter(x=>x!==k);delete state.projectState.known[k];delete state.projectState.missing[k];delete state.projectState.recovered[k];saveProjectState()}state.sessions=state.sessions.filter(x=>x.key!==k);if(state.current?.key===k)clearSelection();renderSessions();renderProjectTabs();toast('Session removed; transcript archive requested','ok');dbg('SESS','Permanent delete completed',{key:k,result:r});setTimeout(()=>state.connected&&loadSessions(),250)}catch(e){showError('Delete failed: '+e.message);toast('Delete failed: '+e.message,'err');dbg('ERROR','sessions.delete: '+e.message,{key:k})}}""")

# One and only one live home. Drops are moves, never copies.
move_helpers="""
function moveSessionToProject(k,targetId){k=String(k||'');if(!k||!state.sessions.some(x=>x.key===k))return;let from=assignedProjectFor(k);for(let p of projects()){p.sessions=p.sessions.filter(x=>x!==k);if(p.activeSession===k)p.activeSession=p.sessions[0]||''}delete state.projectState.missing[k];delete state.projectState.recovered[k];if(targetId!==UNASSIGNED_ID){let target=projects().find(p=>p.id===targetId);if(!target)return;target.sessions.push(k);target.activeSession=k;state.projectState.activeProjectId=target.id}else{state.projectState.activeProjectId=UNASSIGNED_ID;state.projectState.unassignedActive=k}saveProjectState();renderSessions();renderProjectTabs();if(state.current?.key===k)header();toast(targetId===UNASSIGNED_ID?'Moved to Unassigned':`Moved to ${activeProject().name}`,'ok');dbg('SESS','Project move',{key:k,from:from?.id||UNASSIGNED_ID,to:targetId})}
function setupProjectDrop(row,id){row.ondragover=e=>{if(!e.dataTransfer?.types?.includes('text/session-key'))return;e.preventDefault();e.dataTransfer.dropEffect='move';row.classList.add('dragOver')};row.ondragleave=()=>row.classList.remove('dragOver');row.ondrop=e=>{e.preventDefault();row.classList.remove('dragOver');let k=e.dataTransfer.getData('text/session-key');if(k)moveSessionToProject(k,id)}}
"""
one("function addSessionToProject(k,selectIt=true)",move_helpers+"function addSessionToProject(k,selectIt=true)",'move helper insertion')
replace_fn('addSessionToProject',"""function addSessionToProject(k,selectIt=true){let target=state.projectState.activeProjectId===UNASSIGNED_ID?UNASSIGNED_ID:activeProject().id;moveSessionToProject(k,target);if(selectIt&&state.sessions.some(s=>s.key===k))select(k)}""")
