replace_fn('addProject',"""function addProject(){let name=prompt('Project name','New Project');if(name===null)return;name=name.trim();if(!name){toast('Project name cannot be empty','err');return}let p={id:'p-'+uid(),name,sessions:[],activeSession:''};projects().push(p);state.projectState.activeProjectId=p.id;saveProjectState();renderSessions();renderProjectTabs();header();toast('Project created','ok')}""")

replace_fn('deleteProject',"""function deleteProject(id){let ps=projects(),p=ps.find(x=>x.id===id);if(!p)return;if(ps.length===1){toast('Keep at least one project','err');return}if(!confirm(`Remove project “${p.name}”?\n\nIts ${p.sessions.length} session${p.sessions.length===1?'':'s'} will move to Unassigned. OpenClaw sessions are not deleted.`))return;for(let k of p.sessions){let row=state.sessions.find(x=>x.key===k);state.projectState.recovered[k]={label:row?name(row):(knownMeta(k)?.label||k),previousProjectId:p.id,previousProjectName:p.name,recoveredAt:Date.now(),reason:'project-deleted'}}state.projectState.projects=ps.filter(x=>x.id!==id);state.projectState.activeProjectId=UNASSIGNED_ID;state.projectState.unassignedActive=p.sessions.find(k=>state.sessions.some(x=>x.key===k))||'';saveProjectState();let k=state.projectState.unassignedActive;renderSessions();renderProjectTabs();header();k?select(k):clearSelection();toast('Project removed; sessions moved to Unassigned','ok')}""")

replace_fn('switchProject',"""function switchProject(id){if(id!==UNASSIGNED_ID&&!projects().some(p=>p.id===id))return;state.projectState.activeProjectId=id;saveProjectState();let p=activeProject(),k=(p.activeSession&&p.sessions.includes(p.activeSession)?p.activeSession:p.sessions.find(x=>state.sessions.some(s=>s.key===x)))||'';renderSessions();renderProjectTabs();header();k?select(k):clearSelection()}""")

# Left pane: Unassigned + normal projects + Missing + Recycle Bin.
replace_fn('renderProjectSidebar',"""function renderProjectSidebar(){let ps=projects(),ap=activeProject(),un=unassignedSessionKeys(),missing=Object.entries(state.projectState.missing||{}),trash=trashBucket(),deleted=Object.values(trash),live=liveKeySet();$('stats').textContent=`${ps.length} project${ps.length===1?'':'s'} · ${un.length} unassigned · ${missing.length} missing · ${deleted.length} deleted`;let projRows=ps.map(p=>`<div class="projectRow ${state.projectState.activeProjectId===p.id?'active':''}" data-project="${esc(p.id)}" title="Click to open · double-click to rename · drop a session tab here"><span class="projectName">${esc(p.name)}</span><span class="projectCount">${p.sessions.filter(k=>live.has(k)).length}</span>${ps.length>1?`<button class="projectDelete" data-project-delete="${esc(p.id)}" title="Remove project; sessions go to Unassigned">×</button>`:''}</div>`).join(''),missRows=missing.map(([k,m])=>`<div class="exceptionRow"><div class="exceptionInfo"><div class="exceptionTitle">${esc(m.label||k)}</div><div class="exceptionMeta">Previously: ${esc(m.previousProjectName||'Unassigned')} · Missing since ${esc(fmtTime(m.missingSince)||'unknown')}</div></div><button class="exceptionAction danger" data-missing-soft="${esc(k)}" title="Soft delete">×</button></div>`).join(''),binRows=deleted.map(t=>`<div class="exceptionRow"><div class="exceptionInfo"><div class="exceptionTitle">${esc(t.label||t.key)}</div><div class="exceptionMeta">${t.previousProjectName?`Previously: ${esc(t.previousProjectName)} · `:''}Deleted ${esc(fmtTime(t.deletedAt)||'')}</div></div><button class="exceptionAction" data-restore="${esc(t.key)}">Restore</button><button class="exceptionAction danger" data-harddel="${esc(t.key)}">Delete Permanently</button></div>`).join('');$('sessionList').innerHTML=`<div class="projectSectionHead"><span>PROJECTS</span><button id="projectAdd" title="Add project">+</button></div><div class="projectRow systemProjectRow ${state.projectState.activeProjectId===UNASSIGNED_ID?'active':''}" data-project="${UNASSIGNED_ID}" title="Sessions not assigned to a project. Drop a session tab here to unassign it."><span class="projectName">Unassigned</span><span class="projectCount">${un.length}</span></div>${projRows}<div class="exceptionBlock ${state.missingOpen?'open':''}" id="missingBlock"><button class="exceptionHead" id="missingToggle" aria-expanded="${state.missingOpen?'true':'false'}"><span class="chev">›</span><span>Missing (${missing.length})</span></button><div class="exceptionBody">${missRows||'<div class="binEmpty">No missing sessions.</div>'}</div></div><div class="exceptionBlock ${state.trashOpen?'open':''}" id="botsTrash"><button class="exceptionHead" id="botsTrashToggle" aria-expanded="${state.trashOpen?'true':'false'}"><span class="chev">›</span><span>Recycle Bin (${deleted.length})</span></button><div class="exceptionBody">${binRows||'<div class="binEmpty">Recycle Bin is empty.</div>'}</div></div><div class="projectHelp">Drag a session tab onto a Project to move it. Tab × is soft delete and always goes to Recycle Bin.</div>`;$('projectAdd').onclick=addProject;document.querySelectorAll('[data-project]').forEach(n=>{n.onclick=e=>{if(e.target.closest('[data-project-delete]'))return;switchProject(n.dataset.project)};if(n.dataset.project!==UNASSIGNED_ID)n.ondblclick=e=>{if(e.target.closest('[data-project-delete]'))return;renameProject(n.dataset.project)};setupProjectDrop(n,n.dataset.project)});document.querySelectorAll('[data-project-delete]').forEach(b=>b.onclick=e=>{e.stopPropagation();deleteProject(b.dataset.projectDelete)});$('missingToggle').onclick=()=>{state.missingOpen=!state.missingOpen;renderProjectSidebar()};$('botsTrashToggle').onclick=()=>{state.trashOpen=!state.trashOpen;renderProjectSidebar()};document.querySelectorAll('[data-missing-soft]').forEach(b=>b.onclick=()=>softDeleteSession(b.dataset.missingSoft));document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>restoreSession(b.dataset.restore));document.querySelectorAll('[data-harddel]').forEach(b=>b.onclick=()=>permanentDeleteSession(b.dataset.harddel))}""")

# Right tabs are persistent memberships; X means soft-delete. Tabs can be dragged.
replace_fn('renderProjectTabs',"""function renderProjectTabs(){let root=$('projectTabs');if(!root)return;if(state.settings.clientType!=='botschat'){root.innerHTML='';return}let p=activeProject(),ss=p.sessions.map(k=>state.sessions.find(s=>s.key===k)).filter(Boolean);root.innerHTML=ss.map(x=>{let v=sessionState(x.key,x),rec=recoveredMeta(x.key);return`<button class="projectTab ${state.current?.key===x.key?'active':''}" draggable="true" data-project-session="${esc(x.key)}"><span class="sessionState ${statusClass(v)}" title="${statusText(v)}"></span><span class="tabLabel">${esc(name(x))}${rec?' · recovered':''}</span><span class="tabClose" data-project-close="${esc(x.key)}" title="Soft delete → Recycle Bin">×</span></button>`}).join('')+`<button class="projectTabAdd" id="projectTabAdd" title="Add or create session">+</button>`;root.querySelectorAll('[data-project-session]').forEach(b=>{b.onclick=e=>{if(e.target.closest('[data-project-close]'))return;let k=b.dataset.projectSession;setActiveViewSession(k);select(k)};b.ondragstart=e=>{b.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/session-key',b.dataset.projectSession)};b.ondragend=()=>b.classList.remove('dragging')});root.querySelectorAll('[data-project-close]').forEach(b=>b.onclick=e=>{e.stopPropagation();softDeleteSession(b.dataset.projectClose)});$('projectTabAdd').onclick=openProjectSessionPicker}""")

replace_fn('openProjectSessionPicker',"""function openProjectSessionPicker(){let p=activeProject(),available=state.sessions.filter(s=>!trashBucket()[s.key]&&!state.projectState.missing[s.key]&&!p.sessions.includes(s.key));$('modal').innerHTML=`<div class="modalbg"><div class="modal"><div class="mhead"><b>Add session to ${esc(p.name)}</b><span class="grow"></span><button class="btn" id="pickerClose">×</button></div><div class="mbody"><button class="btn primary" id="pickerNew" style="width:100%;margin-bottom:12px">+ Create new OpenClaw session</button><input class="input" id="pickerSearch" placeholder="Find an existing session" style="margin-bottom:10px"><div class="sessionPickerList" id="pickerList"></div></div></div></div>`;let draw=()=>{let q=$('pickerSearch').value.trim().toLowerCase(),a=available.filter(s=>!q||[name(s),s.key,s.preview].some(v=>String(v||'').toLowerCase().includes(q)));$('pickerList').innerHTML=a.length?a.map(s=>{let home=assignedProjectFor(s.key);return`<button class="sessionPick" data-pick="${esc(s.key)}"><span class="sessionState ${statusClass(sessionState(s.key,s))}"></span><span class="pickText"><div class="pickLabel">${esc(name(s))}</div><div class="pickKey">${esc(home?'Currently in '+home.name:'Unassigned')} · ${esc(s.key)}</div></span></button>`}).join(''):'<div class="empty">No additional sessions match.</div>';$('pickerList').querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{let k=b.dataset.pick;$('modal').innerHTML='';addSessionToProject(k,true)})};$('pickerClose').onclick=()=>$('modal').innerHTML='';$('pickerNew').onclick=()=>{$('modal').innerHTML='';newChat()};$('pickerSearch').oninput=draw;draw()}""")

# Keep all known sessions when list changes and transition Missing -> Unassigned.
replace_fn('loadSessions',"""async function loadSessions(){if(!state.connected)return;try{let previous=state.sessions,r=await rpc('sessions.list',{configuredAgentsOnly:true,includeDerivedTitles:true,includeLastMessage:true},30000),a=Array.isArray(r)?r:(r?.sessions||r?.items||[]);state.sessions=a.map(norm).filter(x=>x.key);if(state.settings.clientType==='botschat'){if(!state.projectState)state.projectState=loadProjectState();reconcileProjects(previous)}for(let row of state.sessions)if(!state.sessionStates.has(row.key)){let v=inferredState(row);state.sessionStates.set(row.key,{status:v,runId:null,error:'',updatedAt:Date.now()})}renderSessions();renderProjectTabs();dbg('SESS',`Loaded ${state.sessions.length}`)}catch(e){showError('Unable to load sessions: '+e.message);$('sessionList').innerHTML='<div class="empty">Failed to load sessions.</div>'}}""")

# SOT now includes soft-delete tombstones too.
replace_fn('seedSotOutbox',"""function seedSotOutbox(){if(sotOutbox().length)return;let a=[sotEvent('settings.snapshot',portableSettings()),sotEvent('projects.snapshot',projectSnapshot()),sotEvent('themes.snapshot',themeSnapshot()),sotEvent('trash.snapshot',{scope:trashScope(),bucket:trashBucket()})];saveSotOutbox(a)}""")
replace_fn('applySotEvents',"""function applySotEvents(events){state.sotApplying=true;try{for(let e of events){let p=e?.payload||{};if(e.type==='settings.snapshot'){if(p.clientType)state.settings.clientType=p.clientType==='botschat'?'botschat':'standard';if(p.appearance)state.settings.appearance=normalizeAppearance(p.appearance)}else if(e.type==='projects.snapshot'){if(p.scope===projectScope()&&p.state)state.projectState=normalizeProjectState(p.state)}else if(e.type==='themes.snapshot'){if(Array.isArray(p.themes))localStorage.setItem(K.themes,JSON.stringify({schema:'session-manager-theme-library',version:1,themes:p.themes}))}else if(e.type==='trash.snapshot'){if(p.scope===trashScope()&&p.bucket&&typeof p.bucket==='object'){let all=trashStore();all[trashScope()]=p.bucket;localStorage.setItem(K.trash,JSON.stringify(all))}}}localStorage.setItem(K.settings,JSON.stringify(state.settings));let all={};try{all=JSON.parse(localStorage.getItem(K.projects)||'{}')||{}}catch{}all[projectScope()]=normalizeProjectState(state.projectState||loadProjectState());localStorage.setItem(K.projects,JSON.stringify(all));applyAppearance();applyClientType();renderSessions();renderProjectTabs();header()}finally{state.sotApplying=false}}""")

